// Dataset tooling only: no model calls, generated answers, or network requests.
export const fields=['question','answer','fact_id','category','source'];
export const normalize=q=>q.trim().replace(/\s+/g,' ').toLowerCase();
export function record(value){if(!value||typeof value!=='object'||Array.isArray(value))throw Error('Each record must be an object.');const out={};for(const k of fields){if(value[k]!=null&&typeof value[k]!=='string')throw Error(k+' must be text.');out[k]=value[k]??'';}return out;}
export function parse(text,format){text=text.replace(/^\uFEFF/,'');if(format==='json'){const data=JSON.parse(text);const rows=Array.isArray(data)?data:data.records;if(!Array.isArray(rows))throw Error('Expected an array or a project with records.');return rows.map(record);}if(format==='jsonl')return text.split(/\r?\n/).flatMap((line,i)=>{if(!line.trim())return [];try{return [record(JSON.parse(line))];}catch(e){throw Error('Line '+(i+1)+': '+e.message);}});
if(format!=='csv')throw Error('Use JSONL, JSON, or CSV.');const rows=[];let row=[],cell='',quoted=false,closed=false;
for(let i=0;i<text.length;i++){let c=text[i];if(quoted){if(c==='"'){if(text[i+1]==='"'){cell+='"';i++;}else{quoted=false;closed=true;}}else cell+=c;continue;}if(c==='"'){if(cell||closed)throw Error('Unexpected quote in CSV.');quoted=true;}else if(c===','||c==='\n'||c==='\r'){row.push(cell);cell='';closed=false;if(c!==','){if(row.some(x=>x.length))rows.push(row);row=[];if(c==='\r'&&text[i+1]==='\n')i++;}}else{if(closed)throw Error('Unexpected text after CSV quote.');cell+=c;}}
if(quoted)throw Error('Unclosed CSV quote.');row.push(cell);if(row.some(x=>x.length))rows.push(row);if(!rows.length)return [];const headers=rows.shift().map(h=>h.trim().toLowerCase());if(!headers.includes('question')||!headers.includes('answer')||new Set(headers).size!==headers.length)throw Error('CSV needs unique question and answer headers.');return rows.map((r,i)=>{if(r.length!==headers.length)throw Error('CSV row '+(i+2)+' has the wrong number of columns.');return record(Object.fromEntries(headers.map((h,j)=>[h,r[j]])));});}
export function analyze(rows){const issues=rows.map(()=>[]),seen=new Map;for(let i=0;i<rows.length;i++){const r=rows[i],out=issues[i];if(!r.question.trim())out.push('Question is empty');if(!r.answer.trim())out.push('Answer is empty');if(/[^\x20-\x7e]/.test(r.question+r.answer))out.push('Use printable ASCII in question and answer');if(r.question.length>72)out.push('Question exceeds 72 characters');if(r.question.length+1+r.answer.length>128)out.push('Question + separator + answer exceeds 128');if(r.question!==r.question.trim()||r.answer!==r.answer.trim())out.push('Remove leading or trailing spaces');const key=normalize(r.question);if(!seen.has(key))seen.set(key,[]);seen.get(key).push(i);}
for(const ids of seen.values()){if(ids.length<2)continue;const conflict=new Set(ids.map(i=>rows[i].answer.trim())).size>1;for(const i of ids)issues[i].push(conflict?'Conflicting answers for the same question':'Duplicate question');}
return {issues,invalid:issues.filter(i=>i.length).length,valid:issues.filter(i=>!i.length).length,categories:new Set(rows.map(r=>r.category).filter(Boolean)).size};}
function hash(text){let h=2166136261;for(let i=0;i<text.length;i++){h^=text.charCodeAt(i);h=Math.imul(h,16777619);}h^=h>>>16;h=Math.imul(h,0x85ebca6b);h^=h>>>13;h=Math.imul(h,0xc2b2ae35);h^=h>>>16;return h>>>0;}
export function split(rows,{validation=10,test=10,seed='tiny-1'}={}){if(!Number.isFinite(validation)||!Number.isFinite(test)||validation<0||test<0||validation+test>=100)throw Error('Validation and test must be nonnegative and total less than 100%.');if(analyze(rows).invalid)throw Error('Fix all flagged records before export.');const parent=rows.map((_,i)=>i),find=i=>{while(parent[i]!==i){parent[i]=parent[parent[i]];i=parent[i];}return i;};const seen=new Map;
rows.forEach((r,i)=>{for(const key of ['q:'+normalize(r.question),...(r.fact_id.trim()?['f:'+r.fact_id.trim()]:[])]){if(seen.has(key))parent[find(i)]=find(seen.get(key));else seen.set(key,i);}});
const groups=new Map;rows.forEach((r,i)=>{const k=find(i);if(!groups.has(k))groups.set(k,[]);groups.get(k).push(r);});const result={train:[],validation:[],test:[]};for(const group of groups.values()){const identity=group.map(r=>'q:'+normalize(r.question)).sort().join('\n');const n=hash(seed+'\n'+identity)/4294967296*100;const target=n<test?'test':n<test+validation?'validation':'train';result[target].push(...group);}return result;}
export function jsonl(rows){return rows.map(({question,answer})=>JSON.stringify({question,answer})).join('\n')+(rows.length?'\n':'');}
export function csv(rows){return [fields,...rows.map(r=>fields.map(k=>r[k]))].map(row=>row.map(s=>'"'+String(s).replaceAll('"','""')+'"').join(',')).join('\r\n');}
// Uncompressed ZIP for dependency-free, single-download export.
export function zip(files){const enc=new TextEncoder,parts=[],central=[];let offset=0;const u16=(v,o,n)=>v.setUint16(o,n,true),u32=(v,o,n)=>v.setUint32(o,n,true);
for(const [name,text] of Object.entries(files)){const n=enc.encode(name),data=enc.encode(text);let crc=0xffffffff;for(const b of data){crc^=b;for(let i=0;i<8;i++)crc=(crc>>>1)^((crc&1)?0xedb88320:0);}crc=(crc^0xffffffff)>>>0;const h=new Uint8Array(30+n.length),v=new DataView(h.buffer);u32(v,0,0x04034b50);u16(v,4,20);u16(v,10,0);u16(v,12,33);u32(v,14,crc);u32(v,18,data.length);u32(v,22,data.length);u16(v,26,n.length);h.set(n,30);
const c=new Uint8Array(46+n.length),cv=new DataView(c.buffer);u32(cv,0,0x02014b50);u16(cv,4,20);u16(cv,6,20);u16(cv,14,33);u32(cv,16,crc);u32(cv,20,data.length);u32(cv,24,data.length);u16(cv,28,n.length);u32(cv,42,offset);c.set(n,46);parts.push(h,data);central.push(c);offset+=h.length+data.length;}
const size=central.reduce((n,c)=>n+c.length,0),end=new Uint8Array(22),v=new DataView(end.buffer);u32(v,0,0x06054b50);u16(v,8,central.length);u16(v,10,central.length);u32(v,12,size);u32(v,16,offset);const result=new Uint8Array(offset+size+22);let pos=0;for(const p of [...parts,...central,end]){result.set(p,pos);pos+=p.length;}return result;}
export function bundle(rows,settings){if(!rows.length)throw Error('Add records before exporting.');const sets=split(rows,settings);if(!sets.train.length)throw Error('The split has no training records. Change the seed or percentages.');const project={version:1,settings,records:rows};return {'train.jsonl':jsonl(sets.train),'validation.jsonl':jsonl(sets.validation),'test.jsonl':jsonl(sets.test),'project.json':JSON.stringify(project,null,2),'metadata.csv':csv(rows),'README.txt':`WebTiny dataset export\n\nTrain: ${sets.train.length}\nValidation: ${sets.validation.length}\nTest: ${sets.test.length}\n\nPut train.jsonl beside the extracted training kit, then run:\npython training/train.py --init dist/TINY.BIN --data train.jsonl --val-fraction 0 --steps 1000 --out trained/TINY.BIN\n\nValidation and test files are held out for evaluation; this command does not evaluate them. Keep test data out of training. Fact IDs keep related phrasings together. Split percentages are approximate by fact group, so small datasets may have empty held-out splits. Metadata stays in project.json and metadata.csv; training JSONL contains question and answer only.\n\nNo answers were generated or verified by this tool. Review factual accuracy and source permissions before training.\n`};}
